del /: del[f_, mu_]*ME[Index[Lorentz, mu_], Index[Lorentz, nu_]] := del[f, nu]
 
del[IndexDelta[_, _], _] := 0
 
del[(c_)*(f_), mu_] := c*del[f, mu] /; numQ[c] && FieldQ[f]
 
del[(f_) - (g_), mu_] := del[f, mu] - del[g, mu]
 
del[(f_)/(PRIVATE`a_) - (g_)/(b_), mu_] := 
    del[f, mu]/PRIVATE`a - del[g, mu]/b /; numQ[PRIVATE`a] && numQ[b]
 
del[(f_)/(PRIVATE`a_) + (g_)/(b_), mu_] := 
    del[f, mu]/PRIVATE`a + del[g, mu]/b /; numQ[PRIVATE`a] && numQ[b]
 
del[((c_)*(f_))/(PRIVATE`a_) - ((d_)*(g_))/(b_), mu_] := 
    c*(del[f, mu]/PRIVATE`a) - d*(del[g, mu]/b) /; 
     numQ[PRIVATE`a] && numQ[b] && numQ[c] && numQ[d]
 
del[((c_)*(f_))/(PRIVATE`a_) + ((d_)*(g_))/(b_), mu_] := 
    c*(del[f, mu]/PRIVATE`a) + d*(del[g, mu]/b) /; 
     numQ[PRIVATE`a] && numQ[b] && numQ[c] && numQ[d]
 
del[(f_)/(PRIVATE`a_) - ((d_)*(g_))/(b_), mu_] := 
    del[f, mu]/PRIVATE`a - d*(del[g, mu]/b) /; numQ[PRIVATE`a] && numQ[b] && 
      numQ[d]
 
del[(f_)/(PRIVATE`a_) + ((d_)*(g_))/(b_), mu_] := 
    del[f, mu]/PRIVATE`a + d*(del[g, mu]/b) /; numQ[PRIVATE`a] && numQ[b] && 
      numQ[d]
 
del[((c_)*(f_))/(PRIVATE`a_) - (g_)/(b_), mu_] := 
    c*(del[f, mu]/PRIVATE`a) - del[g, mu]/b /; numQ[PRIVATE`a] && numQ[b] && 
      numQ[c]
 
del[((c_)*(f_))/(PRIVATE`a_) + (g_)/(b_), mu_] := 
    c*(del[f, mu]/PRIVATE`a) + del[g, mu]/b /; numQ[PRIVATE`a] && numQ[b] && 
      numQ[c]
 
del[(PRIVATE`a_)*(f_) - (b_)*(g_), mu_] := 
    del[f, mu]*PRIVATE`a - del[g, mu]*b /; numQ[PRIVATE`a] && numQ[b]
 
del[(PRIVATE`a_)*(f_) + (b_)*(g_), mu_] := 
    del[f, mu]*PRIVATE`a + del[g, mu]*b /; numQ[PRIVATE`a] && numQ[b]
 
del[(f_) + (g_), mu_] := del[f, mu] + del[g, mu]
 
del[((f_) - (g_))/(PRIVATE`a_), mu_] := del[f/PRIVATE`a - g/PRIVATE`a, mu] /; 
     numQ[PRIVATE`a] && FieldQ[f] && FieldQ[g]
 
del[((f_) + (g_))/(PRIVATE`a_), mu_] := del[f/PRIVATE`a + g/PRIVATE`a, mu] /; 
     numQ[PRIVATE`a]
 
del[((b_)*(f_) - (c_)*(g_))/(PRIVATE`a_), mu_] := 
    del[b*(f/PRIVATE`a) - c*(g/PRIVATE`a), mu] /; numQ[PRIVATE`a] && 
      numQ[b] && numQ[c]
 
del[((b_)*(f_) + (c_)*(g_))/(PRIVATE`a_), mu_] := 
    del[b*(f/PRIVATE`a) + c*(g/PRIVATE`a), mu] /; PRIVATE`mumQ[PRIVATE`a] && 
      numQ[b] && numQ[c]
 
del[((b_)*(f_) - (g_))/(PRIVATE`a_), mu_] := 
    del[b*(f/PRIVATE`a) - g/PRIVATE`a, mu] /; numQ[PRIVATE`a] && numQ[b]
 
del[((f_) + (c_)*(g_))/(PRIVATE`a_), mu_] := 
    del[f/PRIVATE`a + c*(g/PRIVATE`a), mu] /; numQ[PRIVATE`a] && numQ[c]
 
del[((f_) - (c_)*(g_))/(PRIVATE`a_), mu_] := 
    del[f/PRIVATE`a - c*(g/PRIVATE`a), mu] /; numQ[PRIVATE`a] && numQ[c]
 
del[(PRIVATE`f1_)?ScalarFieldQ*(PRIVATE`f2_)?ScalarFieldQ, mu_] := 
    PRIVATE`f1*del[PRIVATE`f2, mu] + del[PRIVATE`f1, mu]*PRIVATE`f2
 
del[(PRIVATE`f1_)?ScalarFieldQ*(PRIVATE`f2_)?ScalarFieldQ*
      (PRIVATE`f3_)?ScalarFieldQ, mu_] := 
    PRIVATE`f1*del[PRIVATE`f2*PRIVATE`f3, mu] + del[PRIVATE`f1, mu]*
      PRIVATE`f2*PRIVATE`f3
 
del[(PRIVATE`f1_)?ScalarFieldQ*(PRIVATE`f2_)?ScalarFieldQ*
      (PRIVATE`f3_)?ScalarFieldQ*(PRIVATE`f4_)?ScalarFieldQ, mu_] := 
    PRIVATE`f1*del[PRIVATE`f2*PRIVATE`f3*PRIVATE`f4, mu] + 
     del[PRIVATE`f1, mu]*PRIVATE`f2*PRIVATE`f3*PRIVATE`f4
 
del[(f_)*(g_), mu_] := f*del[g, mu] + del[f, mu]*g
 
del[(PRIVATE`a_) . (b_) . (c___), mu_] := 
    Plus @@ Table[MapAt[del[#1, mu] & , PRIVATE`a . b . c, PRIVATE`kk], 
      {PRIVATE`kk, Length[PRIVATE`a . b . c]}]
 
del[(f_)?FieldQ^2, mu_] := 2*f*del[f, mu]
 
del[(f_)?ScalarFieldQ^(n_), mu_] := n*f^(n - 1)*del[f, mu]
 
del[((xx_) + (y__))^(n_), mu_] := del[Expand[(xx + y)^n], mu]
 
del[PRIVATE`a_, _] := 0 /; numQ[PRIVATE`a]
 
del[field_, mu_, nu_] := del[del[field, mu], nu]
 
del[{PRIVATE`fields__}, mu_] := (del[#1, mu] & ) /@ {PRIVATE`fields}
 
