Conjugate[si[PRIVATE`a_, b_, c_]] ^:= si[PRIVATE`a, c, b]
 
si /: si[mu_, PRIVATE`a_, b_]*si[PRIVATE`ro_, c_, d_]*sibar[nu_, b_, c_] := 
     Module[{PRIVATE`sg}, ME[mu, nu]*si[PRIVATE`ro, PRIVATE`a, d] + 
       ME[PRIVATE`ro, nu]*si[mu, PRIVATE`a, d] - ME[mu, PRIVATE`ro]*
        si[nu, PRIVATE`a, d] - I*Eps[mu, nu, PRIVATE`ro, PRIVATE`sg]*
        si[PRIVATE`sg, PRIVATE`a, d]]
 
si /: si[nu_, b_, c_]*sibar[mu_, PRIVATE`a_, b_]*sibar[PRIVATE`ro_, c_, 
       d_] := Module[{PRIVATE`sg}, ME[mu, nu]*sibar[PRIVATE`ro, PRIVATE`a, 
         d] + ME[PRIVATE`ro, nu]*sibar[mu, PRIVATE`a, d] - 
       ME[mu, PRIVATE`ro]*sibar[nu, PRIVATE`a, d] + 
       I*Eps[mu, nu, PRIVATE`ro, PRIVATE`sg]*sibar[PRIVATE`sg, PRIVATE`a, d]]
 
