HC[IndexDelta][ind__] := IndexDelta[ind]
 
HC[TensDot[xx_, y___]][r_, s_] := (HC /@ Reverse[TensDot[xx, y]])[s, r]
 
HC[Power][PRIVATE`a_, n_] := HC[PRIVATE`a]^n
 
HC[Except[TensDot[_, __], (PRIVATE`tt_)?
        (TensQ[#1] &&  !PRIVATE`StrucConstQ[#1] === True && 
           !PRIVATE`GaugeMatrixQ[#1] === True & )]][ind__, r_, s_] := 
    Conjugate[PRIVATE`tt[ind, r, s]] /; Length[{ind}] + 2 == 
      Length[$IndList[PRIVATE`tt]]
 
HC[Except[TensDot[_, __], (PRIVATE`tt_)?
        (TensQ[#1] &&  !PRIVATE`StrucConstQ[#1] === True && 
           !PRIVATE`GaugeMatrixQ[#1] === True & )]][r_, s_] := 
    Conjugate[PRIVATE`tt[r, s]] /; Length[$IndList[PRIVATE`tt]] == 2
 
HC[(PRIVATE`tt_)?(PRIVATE`StrucConstQ[#1] === True & )][r_, s_, t_] := 
    PRIVATE`tt[r, s, t]
 
HC[(PRIVATE`tt_)?(PRIVATE`GaugeMatrixQ[#1] === True & )][r_, s_, t_] := 
    PRIVATE`tt[r, t, s]
 
HC[(PRIVATE`tt_)?(PRIVATE`GaugeMatrixQ[#1] === True & )][r_] := PRIVATE`tt[r]
 
