SUDot[argx__, (PRIVATE`a_)?(Head[#1] =!= List & )] := SUDot[argx, {PRIVATE`a}]
 
SUDot /: SUDot::usage = "The synthax for a SU(N) invariant product is SUDot[ \
SF, SF, SF, ..., index], where index corresponds to the contracted SU(N) \
index and is contained into the explicit indices of each SF.\nIt works also \
for list of contracted indices.\nA single index is always transformed to a \
list.\nIf a contracted index is on the form EpsUnfold[name], it can be \
explicitely expanded by the function ExpandSUDot."
 
