           !PRIVATE`GaugeMatrixQ[#1] === True & )]][ind__, r_, s_] := 
    Conjugate[PRIVATE`tt[ind, s, r]] /; Length[{ind}] + 2 == 
      Length[$IndList[PRIVATE`tt]]
 
PRIVATE`HCantiPI[Except[TensDot[_, __], (PRIVATE`tt_)?
        (TensQ[#1] &&  !PRIVATE`StrucConstQ[#1] === True && 
